WITH enriched AS (SELECT id, store_name, city, sqft, MAX(sqft) OVER w_grp AS running_max_sqft, SUM(sqft) OVER w_grp AS running_sum_sqft, MIN(sqft) OVER w_grp AS running_min_sqft, PERCENT_RANK() OVER (ORDER BY sqft DESC NULLS FIRST) AS sqft_percent_rank FROM stores WHERE city != 'New York' WINDOW w_grp AS (PARTITION BY region, city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), kept AS (SELECT s.* FROM enriched s WHERE NOT EXISTS (SELECT 1 FROM inventory ch WHERE ch.store_id = s.id AND ch.quantity BETWEEN 141 AND 229)), remaining_keys AS (SELECT id, city FROM kept INTERSECT SELECT id, city FROM stores WHERE store_name LIKE '%Rive%'), reconciled AS (SELECT s.* FROM kept s INNER JOIN remaining_keys k ON s.id = k.id AND s.city = k.city), remaining_keys_2 AS (SELECT city, id FROM reconciled EXCEPT SELECT city, id FROM stores WHERE region NOT IN ('West', 'South', 'East')), kept_rows AS (SELECT s.* FROM reconciled s INNER JOIN remaining_keys_2 k ON s.city = k.city AND s.id = k.id), grouped AS (SELECT city, CASE WHEN sqft_percent_rank >= 0.75 THEN 'PREMIUM' ELSE 'STANDARD' END AS sqft_percent_rank_tier, PERCENTILE_APPROX(sqft_percent_rank, 0.5) AS sqft_percent_rank_p50, ROUND(SUM(running_min_sqft) / NULLIF(COUNT(CASE WHEN city = 'Singapore' THEN 1 END), 0), 2) AS running_min_sqft_per_singapore, BIT_OR(sqft) AS sqft_bit_or FROM kept_rows GROUP BY city, CASE WHEN sqft_percent_rank >= 0.75 THEN 'PREMIUM' ELSE 'STANDARD' END) SELECT city, sqft_percent_rank_tier, running_min_sqft_per_singapore FROM grouped;
